function marcarAtrasados() {
  const aba = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Tarefas');
  const linhas = aba.getDataRange().getValues();
  const hoje = new Date();
  for (let i = 1; i < linhas.length; i++) {   // linha 0 é o cabeçalho
    const prazo = linhas[i][2];
    if (prazo && prazo < hoje) aba.getRange(i + 1, 4).setValue('ATRASADO');
  }
}

