probabilidades = {"relatório": 0.60, "documento": 0.25, "abacaxi": 0.01}

def escolher(probabilidades, temperatura):
    if temperatura == 0:
        # sem sorteio: pega o mais provável
        return max(probabilidades, key=probabilidades.get)
    # temperatura alta "achata" as chances; baixa "afia" as chances
    ajustadas = {t: p ** (1 / temperatura) for t, p in probabilidades.items()}
    total = sum(ajustadas.values())
    return sortear({t: v / total for t, v in ajustadas.items()})

