import json

CATEGORIAS = {'acesso', 'hardware', 'sistema', 'outros'}


def validar(resposta_texto):
    """Devolve um dicionário confiável ou levanta ValueError."""
    inicio = resposta_texto.find('{')      # posição do primeiro {
    fim = resposta_texto.rfind('}')        # posição do último }
    if inicio == -1 or fim == -1:
        raise ValueError('Resposta sem JSON')
    # JSONDecodeError (JSON inválido) também é um tipo de ValueError
    dados = json.loads(resposta_texto[inicio:fim + 1])

    if dados.get('categoria') not in CATEGORIAS:       # valor fora da lista
        raise ValueError(f"Categoria inválida: {dados.get('categoria')}")
    if not isinstance(dados.get('urgente'), bool):     # precisa ser true/false
        raise ValueError('Campo urgente precisa ser true ou false')
    return dados


bruto = 'Claro! Aqui está:\n```json\n{"categoria": "acesso", "urgente": false}\n```'
print(validar(bruto))    # {'categoria': 'acesso', 'urgente': False}

import time
import requests

TENTAVEIS = {429, 500, 502, 503, 504}    # códigos em que vale tentar de novo


def post_com_retentativa(url, max_tentativas=4, **kwargs):
    for tentativa in range(max_tentativas):
        try:
            resposta = requests.post(url, timeout=60, **kwargs)
        except (requests.Timeout, requests.ConnectionError):
            resposta = None                       # falha de rede: vale tentar de novo

        if resposta is not None and resposta.status_code not in TENTAVEIS:
            resposta.raise_for_status()           # 400/401/403: erro nosso, para aqui
            return resposta                       # deu certo

        if tentativa == max_tentativas - 1:
            break                                 # acabaram as tentativas

        espera = 2 ** tentativa                   # 1, 2, 4, 8 segundos...
        if resposta is not None and 'Retry-After' in resposta.headers:
            espera = int(resposta.headers['Retry-After'])   # a API disse quanto esperar
        time.sleep(espera)

    raise RuntimeError(f'Falhou depois de {max_tentativas} tentativas')

